export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-platform-v1","checksum":"bf4ef7e9d340c4de213e08a93d6413c090b4e298b7aae2a1ef3e3799ca9d539f","manifestSha256":"11f69a8cd974929483f117593763c401bb1746038d9439382cddc1a47c773d97","sql":"-- Core schema version identity-platform-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/identity_bind_new_task.sql\n\n-- Every task entry point receives a private project before subsequent writes.\n-- A project-aware creator may replace this default binding in the same transaction.\nCREATE OR REPLACE FUNCTION gov.identity_bind_new_task() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE prior_workspace text:=current_setting('backbone.workspace',true);\nBEGIN\n  -- The tasks INSERT has already passed its own authority checks. The trigger\n  -- binds only that accepted row, including privileged imports without a session.\n  PERFORM set_config('backbone.workspace',NEW.workspace_id::text,true);\n  INSERT INTO app.identity_projects(workspace_id,project_id,owner_id) VALUES(NEW.workspace_id,NEW.id,NEW.requested_by);\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(NEW.workspace_id,NEW.id,NEW.id);\n  INSERT INTO app.identity_project_people(workspace_id,project_id,person_id,access)\n  SELECT NEW.workspace_id,NEW.id,p.id,CASE WHEN p.role='guest' THEN 'viewer' ELSE 'editor' END\n  FROM app.principals p WHERE p.workspace_id=NEW.workspace_id AND p.kind='person' AND p.status='active' AND p.id<>NEW.requested_by\n    AND (p.id=NEW.on_behalf_of OR NEW.visibility='workspace');\n  IF NEW.visibility='workspace' THEN INSERT INTO app.identity_workspace_projects(workspace_id,project_id) VALUES(NEW.workspace_id,NEW.id); END IF;\n  PERFORM set_config('backbone.workspace',coalesce(prior_workspace,''),true);\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.workspace',coalesce(prior_workspace,''),true);\n  RAISE;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_bind_new_task() FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_bind_new_task() TO backbone_owner;\n\n-- sec/t_identity_mutation_context.sql\n\n-- A statement without a live actor must refuse even when project RLS hides all\n-- target rows. Row immutability triggers still check every admitted mutation.\nCREATE FUNCTION sec.t_identity_mutation_context() RETURNS trigger\nLANGUAGE plpgsql SET search_path=pg_catalog\nAS $$\nBEGIN\n  -- The installer can disable storage enforcement to inspect a corrupted ledger.\n  -- Service and owner roles retain the native frozen refusal before RLS filtering.\n  IF NOT (SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user)\n    AND sec.current_principal() IS NULL THEN\n    RAISE EXCEPTION 'frozen: permission denied: mutation requires a live actor';\n  END IF;\n  RETURN NULL;\nEND\n$$;\nREVOKE ALL ON FUNCTION sec.t_identity_mutation_context() FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION sec.t_identity_mutation_context() TO backbone_owner;\n\nSET ROLE backbone_owner;\n\n-- owner/identity_mutation_triggers.sql\n\nCREATE TRIGGER identity_mutation_context BEFORE UPDATE OR DELETE ON app.episodes\nFOR EACH STATEMENT EXECUTE FUNCTION sec.t_identity_mutation_context();\nCREATE TRIGGER identity_mutation_context BEFORE UPDATE OR DELETE ON app.knowledge_candidates\nFOR EACH STATEMENT EXECUTE FUNCTION sec.t_identity_mutation_context();\nCREATE TRIGGER identity_mutation_context BEFORE UPDATE OR DELETE ON app.ledger\nFOR EACH STATEMENT EXECUTE FUNCTION sec.t_identity_mutation_context();\n\nRESET ROLE;\n"} as const);
